        assets["lq_crops"].append(
            {
                "label": f"LQ {year} Q{question}",
                "path": rel,
                "note": (
                    f"Whole exam page stack ({pages_note}); "
                    "no within-page crop. Scaled to show every page."
                ),
            }
        )

